import re

def next_body(html, template):
    token = 'NOT_FOUND'
    for tag in re.findall(r'<input[^>]*>', html):
        if re.search(r'name="_csrf"', tag):
            m = re.search(r'value="([^"]*)"', tag)
            if m:
                token = m.group(1)
                break
    return template.replace('${csrf}', token)

